#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-09
// ============================================================================
// A skill that calls Workflow( must run inline, and its fan-out is not optional
// ============================================================================
// WHAT THIS GUARDS (#4672)
//
//   A `context: fork` skill runs in a forked agent that has the Agent tool but
//   NOT the Workflow tool (measured on CC 2.1.294 with claude -p). /ork:review-pr
//   ran 3 headless reviews as a single pass with 0 Agent and 0 Workflow calls.
//   Operator decision 2026-10-08: these skills run inline, where the Workflow
//   tool exists. review-pr went inline in #4682 and has its own guard
//   (test-review-pr-runs-inline.mjs).
//
//   Inline is necessary but not sufficient: the 2026-10-08 inline proof also
//   made 0 Agent and 0 Workflow calls on the model's own cost judgement. So
//   each skill fixed here carries a `**Fan-out rule:**` line that says a
//   single pass is never a fallback and that skipping the fan-out ends the
//   run as BLOCKED.
//
//   Fails if: any SKILL.md that calls `Workflow(` (or ships a workflows/*.js
//   script, #4696) sets `context: fork`; or one
//   of the skills in FIXED stops calling Workflow( (the list would be stale)
//   or loses its fan-out rule line; or no skill calls Workflow( at all (the
//   scan would be broken).
// ============================================================================

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const SKILLS = path.join(ROOT, 'src', 'skills');
const FIXED = ['assess', 'audit-full', 'brainstorm', 'cover', 'verify'];

const frontmatter = (text) => {
  const m = /^---\n([\s\S]*?)\n---\n/.exec(text);
  return m ? m[1] : '';
};

const failures = [];
const callers = new Map();
for (const name of readdirSync(SKILLS).sort()) {
  const file = path.join(SKILLS, name, 'SKILL.md');
  if (!existsSync(file)) continue;
  const text = readFileSync(file, 'utf8');
  // A skill also runs Workflow when it ships a workflows/*.js script (brainstorm,
  // #4696): its body names the script file, not a literal Workflow( call.
  const wfDir = path.join(SKILLS, name, 'workflows');
  const shipsScript = existsSync(wfDir) && readdirSync(wfDir).some((f) => f.endsWith('.js'));
  if (!/\bWorkflow\(/.test(text) && !shipsScript) continue;
  callers.set(name, text);
  if (/^context:\s*fork\s*$/m.test(frontmatter(text))) {
    failures.push(`src/skills/${name}/SKILL.md: calls Workflow( but sets context: fork (a fork has no Workflow tool, #4672)`);
  }
}

if (callers.size === 0) {
  console.log('FAIL: no skill calls Workflow(; the scan is broken');
  process.exit(1);
}

for (const name of FIXED) {
  const text = callers.get(name);
  if (text === undefined) {
    failures.push(`src/skills/${name}/SKILL.md: no longer calls Workflow( or ships a workflows/*.js script; update FIXED in this test`);
    continue;
  }
  const line = text.split('\n').find((l) => l.startsWith('**Fan-out rule:**'));
  if (!line) {
    failures.push(`src/skills/${name}/SKILL.md: no **Fan-out rule:** line at its Workflow default`);
    continue;
  }
  if (!/a single pass is never a fallback/i.test(line)) {
    failures.push(`src/skills/${name}/SKILL.md: fan-out rule does not say "a single pass is never a fallback"`);
  }
  if (!/\bBLOCKED\b/.test(line)) {
    failures.push(`src/skills/${name}/SKILL.md: fan-out rule does not end a skipped fan-out as BLOCKED`);
  }
}

for (const f of failures) console.log(`FAIL: ${f}`);
if (failures.length) process.exit(1);
console.log(`PASS: ${callers.size} skills call Workflow(, none sets context: fork, and ${FIXED.length} carry the fan-out rule`);
